import { loadFont } from "@remotion/google-fonts/Baloo2";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
import { NOVO, V2 } from "./tempoV4";

// Salve o Pietro (cliente Gabrie Alberti, 16/10): vitrine com as 3 fotos e os 3 vídeos da família, lettering embaixo num
// bloco azul-marinho, como no site salveopietro.com.br (Baloo 2, azul #06366d/#04264d, verde do botão de doar).
// Locução: audio/gabrie-vo.wav (o locutor sem os silêncios mortos + fala da mãe). Tempos = vídeo da v1 (56,2 s); a v2 (16/10)
// abriu em 28,2 s a cena do valor arrecadado (10,48 s, motion), e toOld converte o tempo novo no da v1.
// v2: degradê mais leve, transições mais suaves (dissolve e desfoque, sem empurrão nem cortina), coração no "AMOR",
// rota Brasil → México no "México" e a cena do arrecadado.

const { fontFamily: F } = loadFont("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const PI_FPS = 30;
const OLD_END = 56.2;
const INS_A = 28.2;
const INS_LEN = 10.48;
const INS_B = INS_A + INS_LEN;
// v4: voz da v3 com abertura regravada, a 1,25x (audio/gabrie-vo-v4.wav; v3 usava tempoV3). Tudo continua escrito no tempo da v2; v2Of converte o tempo novo.
export const PI_DUR = NOVO[NOVO.length - 1];
const v2Of = (t: number) => interpolate(t, NOVO, V2, cl);
const novoOf = (t: number) => interpolate(t, V2, NOVO, cl);
const toOld = (T: number) => (T < INS_A ? T : T < INS_B ? INS_A - 0.01 : T - INS_LEN);
const toNew = (a: number) => (a < INS_A ? a : a + INS_LEN);
export const PI_FRAMES = Math.round(PI_DUR * PI_FPS);

const NAVY = "#04264d";
const NAVY2 = "#06366d";
const BLUE = "#3b8ddf";
const GREEN = "#4ade80";
const PINK = "#ff5c8a";
const COL = 840; // coluna central, margem de 120

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IO = Easing.inOut(Easing.sin);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

// ───────── cenas com foto ou vídeo em tela cheia ─────────
type Tr = "fade" | "push" | "zoom" | "wipe" | "blur";
type Sc = {
  a: number; b: number; tr: Tr;
  img?: string; vid?: string; from?: number; rate?: number;
  z: [number, number]; o: string; pan?: [number, number]; // escala início→fim, origem, deslize horizontal (px)
};
const SC: Sc[] = [
  { a: 0, b: 2.95, tr: "fade", img: "foto-1.jpg", z: [1.2, 1.06], o: "50% 40%" },
  { a: 2.95, b: 7.2, tr: "fade", vid: "video-2.mp4", from: 0, rate: 0.72, z: [1.3, 1.38], o: "50% 75%" },
  { a: 7.2, b: 12.0, tr: "zoom", img: "foto-2.jpg", z: [1.04, 1.14], o: "40% 55%", pan: [18, -18] },
  { a: 12.0, b: 16.5, tr: "blur", vid: "video-1.mp4", from: 0, rate: 0.55, z: [1.06, 1.16], o: "50% 35%" },
  { a: 16.5, b: 21.1, tr: "fade", vid: "video-3.mp4", from: 9.8, rate: 0.7, z: [1.16, 1.06], o: "50% 40%" },
  { a: 21.1, b: 28.2, tr: "zoom", vid: "video-3.mp4", from: 13.0, rate: 0.69, z: [1.04, 1.14], o: "40% 45%" },
  { a: 28.2, b: 36.1, tr: "zoom", img: "foto-3.jpg", z: [1.1, 1.24], o: "62% 38%", pan: [-14, 10] },
  { a: 36.1, b: 41.3, tr: "fade", vid: "video-3.mp4", from: 0, rate: 0.6, z: [1.25, 1.15], o: "45% 35%" },
];
const TR_D: Record<Tr, number> = { fade: 0.9, push: 0.9, zoom: 1.0, wipe: 0.9, blur: 1.0 };

const Scene: React.FC<{ t: number; s: Sc; first: boolean }> = ({ t, s, first }) => {
  const d = TR_D[s.tr];
  const e = first ? 1 : interpolate(t, [s.a - d * 0.5, s.a + d * 0.5], [0, 1], { ...cl, easing: IO });
  const u = interpolate(t, [s.a, s.b + 0.6], [0, 1], { ...cl, easing: IO });
  let sc = s.z[0] + (s.z[1] - s.z[0]) * u;
  const px = s.pan ? s.pan[0] + (s.pan[1] - s.pan[0]) * u : 0;
  const wrap: React.CSSProperties = { overflow: "hidden" };
  if (s.tr === "fade") wrap.opacity = e;
  if (s.tr === "push") wrap.transform = `translateY(${((1 - e) * 1920).toFixed(1)}px)`;
  if (s.tr === "zoom") { wrap.opacity = e; sc *= 1 + 0.06 * (1 - e); }
  if (s.tr === "wipe") wrap.clipPath = `inset(0 ${((1 - e) * 100).toFixed(2)}% 0 0)`;
  if (s.tr === "blur") { wrap.opacity = e; wrap.filter = e < 1 ? `blur(${((1 - e) * 10).toFixed(1)}px)` : undefined; }
  const media: React.CSSProperties = { width: "100%", height: "100%", objectFit: "cover", transform: `translateX(${px.toFixed(1)}px) scale(${sc.toFixed(4)})`, transformOrigin: s.o };
  return (
    <AbsoluteFill style={{ ...wrap, background: NAVY }}>
      {s.img ? (
        <Img src={staticFile(`gabrie/${s.img}`)} style={media} />
      ) : (
        <OffthreadVideo src={staticFile(`gabrie/${s.vid}`)} muted trimBefore={Math.round((s.from ?? 0) * PI_FPS)} playbackRate={s.rate ?? 1} style={media} />
      )}
      {s.vid === "video-2.mp4" ? <div style={{ position: "absolute", left: 0, right: 0, top: 1340, height: 580, background: "linear-gradient(180deg, rgba(4,38,77,0) 0%, rgba(4,38,77,0.92) 26%, #04264d 40%, #04264d 100%)" }} /> : null}
    </AbsoluteFill>
  );
};

// ───────── lettering: cada frase no mesmo lugar; a anterior some inteira antes de a próxima entrar ─────────
type Ln = { w: string; at: number; hl?: boolean; size?: number };
type Ph = { out: number; lines: Ln[]; plane?: number; heart?: number };
const PH: Ph[] = [
  { out: 2.85, lines: [{ w: "O Pietro", at: 0.2 }, { w: "NASCEU SAUDÁVEL", at: 1.15, hl: true }] },
  { out: 4.95, lines: [{ w: "um bebê", at: 3.08 }, { w: "MUITO SONHADO", at: 3.55, hl: true }] },
  { out: 7.1, lines: [{ w: "esperado com", at: 5.1 }, { w: "AMOR", at: 6.35, hl: true, size: 150 }], heart: 6.45 },
  { out: 11.9, lines: [{ w: "com 1 mês e 3 dias", at: 7.4 }, { w: "DE VIDA", at: 10.42, hl: true, size: 130 }] },
  { out: 14.0, lines: [{ w: "um engasgo com", at: 12.1 }, { w: "LEITE MATERNO", at: 12.93, hl: true }] },
  { out: 16.45, lines: [{ w: "causou uma", at: 14.06 }, { w: "LESÃO CEREBRAL", at: 14.95, hl: true }] },
  { out: 21.0, lines: [{ w: "hoje ele vive com", at: 16.7 }, { w: "PARALISIA CEREBRAL", at: 18.8, hl: true }, { w: "GRAVE", at: 20.14, hl: true }] },
  { out: 23.8, lines: [{ w: "a família luta para levá-lo ao", at: 21.26 }, { w: "MÉXICO", at: 22.9, hl: true, size: 140 }] },
  { out: 26.55, lines: [{ w: "um tratamento em busca de mais", at: 23.82 }, { w: "CONFORTO", at: 25.52, hl: true, size: 130 }] },
  { out: 28.1, lines: [{ w: "e", at: 26.62 }, { w: "QUALIDADE DE VIDA", at: 26.72, hl: true }] },
  { out: 31.3, lines: [{ w: "R$ 20", at: 28.82, hl: true, size: 170 }, { w: "já ajudam", at: 29.88 }] },
  { out: 34.4, lines: [{ w: "e se muita gente", at: 31.38 }, { w: "DOAR POUCO", at: 32.74, hl: true, size: 120 }] },
  { out: 36.05, lines: [{ w: "o Pietro", at: 34.45 }, { w: "EMBARCA", at: 35.03, hl: true, size: 140 }], plane: 35.03 },
];
// largura média por letra na Baloo 2: 0,5 (600) e 0,6 (800 em caixa-alta)
const fit = (l: Ln) => l.size ?? Math.min(l.hl ? 112 : 80, Math.floor(COL / (l.w.length * (l.hl ? 0.6 : 0.5))));

const Plane: React.FC<{ e: number; s: number }> = ({ e, s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" style={{ opacity: Math.min(1, e * 2), transform: `translate(${((1 - e) * -60).toFixed(1)}px, ${((1 - e) * 30).toFixed(1)}px) rotate(${(-12 * (1 - e)).toFixed(1)}deg)` }}>
    <path d="M21 16v-2l-8-5V3.5a1.5 1.5 0 0 0-3 0V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5l8 2.5z" fill={GREEN} />
  </svg>
);

const HeartDraw: React.FC<{ e: number; s: number }> = ({ e, s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" style={{ overflow: "visible" }}>
    <path d="M12 21s-7.5-4.6-9.6-9.2C.9 8.4 3 4.5 6.8 4.5c2.1 0 3.6 1.1 5.2 3 1.6-1.9 3.1-3 5.2-3 3.8 0 5.9 3.9 4.4 7.3C19.5 16.4 12 21 12 21z" fill={PINK} fillOpacity={Math.max(0, (e - 0.6) / 0.4)} stroke={PINK} strokeWidth={1.8} strokeLinejoin="round" pathLength={1} strokeDasharray="1" strokeDashoffset={(1 - Math.min(1, e / 0.7)).toFixed(3)} />
  </svg>
);

// ───────── inserção: rota Brasil → México sobre o vídeo, quando a fala diz "México" ─────────
const Route: React.FC<{ t: number }> = ({ t }) => {
  const A = 22.85, B = 25.6;
  if (t < A || t > B + 0.4) return null;
  const o = k(t, A, 0.5) * (1 - lin(t, B, B + 0.4));
  const draw = interpolate(t, [A + 0.2, A + 1.6], [0, 1], { ...cl, easing: IO });
  const pin2 = k(t, A + 1.4, 0.5);
  // arco de (800, 600) Brasil até (280, 380) México, em coordenadas do quadro
  const P = (u: number) => {
    const x0 = 800, y0 = 600, cx = 560, cy = 230, x1 = 280, y1 = 380;
    return [(1 - u) ** 2 * x0 + 2 * (1 - u) * u * cx + u * u * x1, (1 - u) ** 2 * y0 + 2 * (1 - u) * u * cy + u * u * y1];
  };
  const [px, py] = P(draw);
  const [qx, qy] = P(Math.min(1, draw + 0.01));
  const ang = (Math.atan2(qy - py, qx - px) * 180) / Math.PI + 90;
  const Pin: React.FC<{ x: number; y: number; label: string; e: number; c: string }> = ({ x, y, label, e, c }) => (
    <div style={{ position: "absolute", left: x - 150, top: y - 22, width: 300, display: "flex", flexDirection: "column", alignItems: "center", opacity: e, transform: `scale(${(0.7 + 0.3 * e).toFixed(3)})` }}>
      <div style={{ width: 44, height: 44, borderRadius: 99, background: c, border: "6px solid #fff", boxShadow: "0 6px 18px rgba(0,0,0,0.35)" }} />
      <div style={{ marginTop: 10, padding: "6px 22px", borderRadius: 99, background: "rgba(4,38,77,0.82)", fontFamily: F, fontWeight: 700, fontSize: 38, color: "#fff" }}>{label}</div>
    </div>
  );
  return (
    <AbsoluteFill style={{ opacity: o }}>
      {/* linha pontilhada que nasce atrás do avião (máscara com o traço revelado até o ponto) */}
      <svg width={1080} height={1920} style={{ position: "absolute", inset: 0, filter: "drop-shadow(0 2px 6px rgba(0,0,0,0.5))" }}>
        <defs>
          <mask id="rota">
            <path d="M800 600 Q560 230 280 380" fill="none" stroke="#fff" strokeWidth={16} pathLength={1} strokeDasharray={`${draw.toFixed(4)} 1`} />
          </mask>
        </defs>
        <path d="M800 600 Q560 230 280 380" fill="none" stroke="#fff" strokeWidth={6} strokeLinecap="round" strokeDasharray="2 20" mask="url(#rota)" />
      </svg>
      <Pin x={800} y={600} label="Brasil" e={k(t, A, 0.5)} c={BLUE} />
      <Pin x={280} y={380} label="México" e={pin2} c={GREEN} />
      <div style={{ position: "absolute", left: px - 36, top: py - 36, width: 72, height: 72, transform: `rotate(${ang.toFixed(1)}deg)`, opacity: draw < 1 ? 1 : 1 - pin2 }}>
        <svg width={72} height={72} viewBox="0 0 24 24"><path d="M21 16v-2l-8-5V3.5a1.5 1.5 0 0 0-3 0V9l-8 5v2l8-2.5V19l-2 1.5V22l3.5-1 3.5 1v-1.5L13 19v-5.5l8 2.5z" fill="#fff" /></svg>
      </div>
    </AbsoluteFill>
  );
};

const Lettering: React.FC<{ t: number }> = ({ t }) => (
  <>
    {PH.map((p, i) => {
      if (t < p.lines[0].at - 0.02 || t > p.out + 0.2) return null;
      const o = lin(t, p.out, p.out + 0.16);
      return (
        <div key={i} style={{ position: "absolute", left: 120, right: 120, top: 1480, height: 360, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", opacity: 1 - o, filter: o > 0 ? `blur(${(o * 12).toFixed(1)}px)` : undefined }}>
          {p.lines.map((l, j) => {
            const e = k(t, l.at, l.hl ? 0.5 : 0.4);
            const s = fit(l);
            const isLast = j === p.lines.length - 1;
            return (
              <div key={j} style={{ display: "flex", alignItems: "center", gap: 22, fontFamily: F, fontSize: s, lineHeight: 1.04, whiteSpace: "nowrap", fontWeight: l.hl ? 800 : 600, letterSpacing: l.hl ? "-0.01em" : "-0.02em", color: l.hl ? GREEN : "#FFFFFF", opacity: Math.min(1, e * 1.8), transform: `translateY(${((1 - e) * 24).toFixed(1)}px) scale(${(l.hl ? 0.9 + 0.1 * e : 1).toFixed(3)})`, filter: `blur(${((1 - e) * 12).toFixed(1)}px)`, textShadow: "0 3px 16px rgba(2,20,45,0.75), 0 0 2px rgba(2,20,45,0.5)", marginTop: j > 0 ? 4 : 0 }}>
                {l.w}
                {p.plane !== undefined && isLast ? <Plane e={k(t, p.plane + 0.1, 0.6)} s={s * 0.8} /> : null}
                {p.heart !== undefined && isLast ? <HeartDraw e={lin(t, p.heart, p.heart + 0.7)} s={s * 0.78} /> : null}
              </div>
            );
          })}
        </div>
      );
    })}
  </>
);

// selo no alto, como o "Um pedido da família" do site
const Heart: React.FC<{ s: number; c?: string }> = ({ s, c = PINK }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><path d="M12 21s-7.5-4.6-9.6-9.2C.9 8.4 3 4.5 6.8 4.5c2.1 0 3.6 1.1 5.2 3 1.6-1.9 3.1-3 5.2-3 3.8 0 5.9 3.9 4.4 7.3C19.5 16.4 12 21 12 21z" fill={c} /></svg>
);
const Tag: React.FC<{ t: number }> = ({ t }) => {
  const e = k(t, 0.5, 0.7);
  const o = 1 - lin(t, 36.0, 36.3); // sai na fala da mãe; as cenas azuis do fim não levam selo
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top: 130, display: "flex", justifyContent: "center", opacity: e * o, transform: `translateY(${((1 - e) * -18).toFixed(1)}px)` }}>
      <div style={{ display: "flex", alignItems: "center", gap: 14, padding: "14px 30px", borderRadius: 999, background: "rgba(4,38,77,0.78)", border: "2px solid rgba(255,255,255,0.18)", fontFamily: F, fontWeight: 700, fontSize: 30, letterSpacing: "0.16em", color: "#fff" }}>
        <Heart s={30} /> SALVE O PIETRO
      </div>
    </div>
  );
};

// ───────── fala da mãe: citação no centro, linhas que se somam no mesmo bloco ─────────
const QUOTE: Ln[] = [
  { w: "“A gente jamais", at: 36.42 },
  { w: "iria conseguir", at: 37.04 },
  { w: "se não fosse a ajuda", at: 38.54 },
  { w: "de cada um de vocês.”", at: 39.65 },
];
const Quote: React.FC<{ t: number }> = ({ t }) => {
  if (t < 36.0 || t > 41.6) return null;
  const bg = lin(t, 36.05, 36.5) * (1 - lin(t, 41.2, 41.5));
  const o = 1 - lin(t, 41.1, 41.3);
  const sig = k(t, 40.3, 0.6);
  return (
    <>
      <AbsoluteFill style={{ background: `rgba(4,38,77,${(0.62 * bg).toFixed(3)})` }} />
      <div style={{ position: "absolute", left: 120, right: 120, top: 560, height: 800, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", opacity: o }}>
        {QUOTE.map((l, j) => {
          const e = k(t, l.at, 0.45);
          return (
            <div key={j} style={{ fontFamily: F, fontWeight: 700, fontSize: 82, lineHeight: 1.12, color: j >= 2 ? GREEN : "#fff", whiteSpace: "nowrap", opacity: Math.min(1, e * 1.8), transform: `translateY(${((1 - e) * 22).toFixed(1)}px)`, filter: `blur(${((1 - e) * 10).toFixed(1)}px)`, textShadow: "0 4px 22px rgba(0,0,0,0.45)" }}>
              {l.w}
            </div>
          );
        })}
        <div style={{ marginTop: 44, display: "flex", alignItems: "center", gap: 14, fontFamily: F, fontWeight: 600, fontSize: 40, color: "rgba(255,255,255,0.9)", opacity: sig, transform: `translateY(${((1 - sig) * 16).toFixed(1)}px)` }}>
          <Heart s={34} /> família do Pietro
        </div>
      </div>
    </>
  );
};

// ───────── formas de ajudar e fecho (fundo azul do site) ─────────
const ICONS: Record<string, React.ReactNode> = {
  pix: <path d="M12 2.5 21.5 12 12 21.5 2.5 12z M12 7.5 16.5 12 12 16.5 7.5 12z" fill="none" stroke="#fff" strokeWidth={2.2} strokeLinejoin="round" />,
  card: <><rect x="2.5" y="5" width="19" height="14" rx="2.5" fill="none" stroke="#fff" strokeWidth={2.2} /><path d="M2.5 10h19" stroke="#fff" strokeWidth={2.2} /></>,
  rifa: <path d="M3 7.5h18v3a1.5 1.5 0 0 0 0 3v3H3v-3a1.5 1.5 0 0 0 0-3z M14 7.5v9" fill="none" stroke="#fff" strokeWidth={2.2} strokeLinejoin="round" strokeDasharray="0" />,
  dindo: <><circle cx="9" cy="8" r="3.4" fill="none" stroke="#fff" strokeWidth={2.2} /><path d="M2.8 20c.6-3.6 3-5.6 6.2-5.6s5.6 2 6.2 5.6" fill="none" stroke="#fff" strokeWidth={2.2} strokeLinecap="round" /><path d="M17.5 8.5c1-1.3 3.4-.8 3.4 1 0 1.6-3.4 3.5-3.4 3.5s-3.4-1.9-3.4-3.5c0-1.8 2.4-2.3 3.4-1z" fill={PINK} /></>,
};
const WAYS: { id: string; w: string; at: number }[] = [
  { id: "pix", w: "Pix", at: 41.6 },
  { id: "card", w: "Cartão", at: 42.42 },
  { id: "rifa", w: "Rifa", at: 43.46 },
  { id: "dindo", w: "Ser Dindo(a)", at: 44.84 },
];
const BgNavy: React.FC<{ t: number; a: number }> = ({ t, a }) => {
  const u = lin(t, a, OLD_END);
  return <AbsoluteFill style={{ background: `radial-gradient(120% 70% at 50% ${(30 + 14 * u).toFixed(1)}%, ${NAVY2} 0%, ${NAVY} 62%, #021a36 100%)` }} />;
};
const Ways: React.FC<{ t: number }> = ({ t }) => {
  const A = 41.3;
  if (t < A - 0.05 || t > 49.75) return null;
  const e = k(t, A, 0.5);
  const o = 1 - lin(t, 49.3, 49.6);
  const title = k(t, 46.58, 0.5);
  const ph = k(t, A + 0.1, 0.7);
  const drift = interpolate(t, [A, 49.6], [1.0, 1.12], cl);
  return (
    <AbsoluteFill style={{ clipPath: `circle(${(e * 150).toFixed(1)}% at 50% 50%)`, opacity: o }}>
      <BgNavy t={t} a={A} />
      {/* câmera lenta no conjunto, para a cena não ficar parada */}
      <AbsoluteFill style={{ transform: `scale(${interpolate(t, [A, 49.6], [1.0, 1.06], { ...cl, easing: IO }).toFixed(4)}) translateY(${interpolate(t, [A, 49.6], [12, -16], cl).toFixed(1)}px)` }}>
      {/* retrato da família no alto, como o avatar do site */}
      <div style={{ position: "absolute", left: 540 - 190, top: 330, width: 380, height: 380, borderRadius: 999, overflow: "hidden", border: `8px solid ${GREEN}`, boxShadow: "0 18px 50px rgba(0,0,0,0.4)", opacity: ph, transform: `scale(${(0.85 + 0.15 * ph).toFixed(3)})` }}>
        <Img src={staticFile("gabrie/foto-3.jpg")} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "60% 30%", transform: `scale(${(1.55 * drift).toFixed(3)})`, transformOrigin: "62% 34%" }} />
      </div>
      <div style={{ position: "absolute", left: 120, right: 120, top: 790, display: "grid", gridTemplateColumns: "1fr 1fr", gap: 28 }}>
        {WAYS.map((w) => {
          const c = k(t, w.at, 0.45);
          return (
            <div key={w.id} style={{ height: 210, borderRadius: 34, background: "rgba(255,255,255,0.08)", border: "2px solid rgba(255,255,255,0.16)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 14, opacity: Math.min(1, c * 1.6), transform: `translateY(${((1 - c) * 40).toFixed(1)}px) scale(${(0.88 + 0.12 * c).toFixed(3)})` }}>
              <svg width={76} height={76} viewBox="0 0 24 24">{ICONS[w.id]}</svg>
              <div style={{ fontFamily: F, fontWeight: 700, fontSize: 52, color: "#fff", whiteSpace: "nowrap" }}>{w.w}</div>
            </div>
          );
        })}
      </div>
